PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS restaurants(restaurant_id TEXT PRIMARY KEY,name TEXT NOT NULL,plan TEXT NOT NULL CHECK(plan IN('STANDARD','PLUS')),onboarding_date TEXT NOT NULL,rating TEXT NOT NULL,packaging_charge TEXT NOT NULL,weekly_ad_budget TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ACTIVE','SUSPENDED')));
CREATE TABLE IF NOT EXISTS orders(order_id TEXT PRIMARY KEY,restaurant_id TEXT NOT NULL REFERENCES restaurants(restaurant_id),order_time TEXT NOT NULL,items_gross TEXT NOT NULL,restaurant_discount TEXT NOT NULL,platform_discount TEXT NOT NULL,cofund_discount TEXT NOT NULL,packaging TEXT NOT NULL,distance TEXT NOT NULL,payment_mode TEXT NOT NULL,outcome TEXT NOT NULL,refund_reason TEXT NOT NULL,refund_amount TEXT NOT NULL,dispute_status TEXT NOT NULL,cancel_seconds INTEGER NOT NULL DEFAULT 0,accepted INTEGER NOT NULL DEFAULT 1,dispute_closed_at TEXT NOT NULL DEFAULT '',processed_at TEXT NOT NULL,delivery_fee TEXT NOT NULL DEFAULT '0',platform_fee TEXT NOT NULL DEFAULT '0',rating TEXT NOT NULL DEFAULT '',customer_refund TEXT NOT NULL DEFAULT '0',settlement_id INTEGER REFERENCES settlements(settlement_id));
CREATE TABLE IF NOT EXISTS order_items(order_id TEXT NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,line_no INTEGER NOT NULL,name TEXT NOT NULL,quantity TEXT NOT NULL,unit_price TEXT NOT NULL,PRIMARY KEY(order_id,line_no));
CREATE TABLE IF NOT EXISTS disputes(dispute_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(order_id),opened_at TEXT NOT NULL,closed_at TEXT NOT NULL DEFAULT '',resolution TEXT NOT NULL DEFAULT '',refund_amount TEXT NOT NULL DEFAULT '0.00',refund_reason TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS settlements(settlement_id INTEGER PRIMARY KEY AUTOINCREMENT,restaurant_id TEXT NOT NULL REFERENCES restaurants(restaurant_id),week_start TEXT NOT NULL,gross TEXT NOT NULL,restaurant_discounts TEXT NOT NULL,platform_discounts TEXT NOT NULL,packaging TEXT NOT NULL,delivery_fees TEXT NOT NULL,platform_fees TEXT NOT NULL,commission TEXT NOT NULL,gst_95 TEXT NOT NULL,commission_gst TEXT NOT NULL,tds TEXT NOT NULL,refunds TEXT NOT NULL,platform_refunds TEXT NOT NULL,ads TEXT NOT NULL,penalties TEXT NOT NULL,reimbursements TEXT NOT NULL,payout TEXT NOT NULL,carried_debit TEXT NOT NULL,order_ids TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(restaurant_id,week_start));
CREATE TABLE IF NOT EXISTS settlement_audit(audit_id INTEGER PRIMARY KEY AUTOINCREMENT,settlement_id INTEGER NOT NULL REFERENCES settlements(settlement_id),order_id TEXT NOT NULL REFERENCES orders(order_id),gross TEXT NOT NULL,commission TEXT NOT NULL,platform_fee TEXT NOT NULL,delivery_fee TEXT NOT NULL,tds TEXT NOT NULL,refund TEXT NOT NULL,breakup_json TEXT NOT NULL DEFAULT '{}',recorded_at TEXT NOT NULL,UNIQUE(settlement_id,order_id));
CREATE TABLE IF NOT EXISTS settlement_corrections(correction_id INTEGER PRIMARY KEY AUTOINCREMENT,settlement_id INTEGER NOT NULL REFERENCES settlements(settlement_id),revision INTEGER NOT NULL,reason TEXT NOT NULL,previous_statement TEXT NOT NULL,corrected_statement TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(settlement_id,revision));
CREATE TABLE IF NOT EXISTS settlement_correction_audit(correction_audit_id INTEGER PRIMARY KEY AUTOINCREMENT,correction_id INTEGER NOT NULL REFERENCES settlement_corrections(correction_id),order_id TEXT NOT NULL REFERENCES orders(order_id),breakup_json TEXT NOT NULL,recorded_at TEXT NOT NULL,UNIQUE(correction_id,order_id));
CREATE TABLE IF NOT EXISTS processing_history(file_hash TEXT PRIMARY KEY,file_name TEXT NOT NULL,processed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ad_debits(restaurant_id TEXT PRIMARY KEY,amount TEXT NOT NULL);
